require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/ManagementMeetingsRepository.php';Auth::requireLogin();$u=Auth::user();$id=(int)($_GET['id']??$_POST['meeting_id']??0);$meeting=ManagementMeetingsRepository::getMeetingById($id,$u);if(!$meeting){http_response_code(404);exit('صورتجلسه در دسترس نیست.');}if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Auth::verifyCsrf($_POST['_csrf']??null))throw new DomainException('اعتبار فرم منقضی شده است.');$decisionId=ManagementMeetingsRepository::createDecision($_POST,(int)$u['id']);flash('مصوبه با موفقیت ثبت شد.');redirect('/admin/management-decision-view.php?id='.$decisionId);}catch(InvalidArgumentException|DomainException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('Meeting decision create: '.$e->getMessage());flash('ثبت مصوبه انجام نشد.','danger');}redirect('/admin/management-meeting-view.php?id='.$id.'#decisionForm');}$decisions=ManagementMeetingsRepository::getDecisions(['meeting_id'=>$id],$u);$users=ManagementMeetingsRepository::users();$units=ManagementMeetingsRepository::units();$userMap=array_column($users,'name','id');$pageTitle='جزئیات صورتجلسه';$adminExtraStylesheets=['/assets/css/management-governance.css'];require __DIR__.'/../views/partials/admin-header.php';?>
<div class="mg-page"><header class="mg-hero"><div><small>صورتجلسه شماره <?=$meeting['id']?></small><h1><?=e($meeting['title'])?></h1><p><?=e(JalaliDate::toJalali($meeting['meeting_date']))?> · <?=e($meeting['location']?:'محل ثبت نشده')?></p></div><div class="mg-actions"><a class="btn" href="/admin/management-meetings.php">بازگشت</a><?php if(ManagementMeetingsRepository::canCreateMeeting($u)):?><a class="btn" href="#decisionForm">ثبت مصوبه</a><?php endif?></div></header><?php require __DIR__.'/includes/management-governance-nav.php';?><section class="card"><div class="mg-detail-grid"><div class="mg-detail"><span>نوع جلسه</span><strong><?=e($meeting['meeting_type'])?></strong></div><div class="mg-detail"><span>برگزارکننده</span><strong><?=e($meeting['organizer_name']??'—')?></strong></div><div class="mg-detail"><span>دبیر جلسه</span><strong><?=e($meeting['secretary_name']??'—')?></strong></div><div class="mg-detail"><span>ساعت</span><strong><?=e(substr((string)$meeting['start_time'],0,5).' تا '.substr((string)$meeting['end_time'],0,5))?></strong></div><div class="mg-detail"><span>وضعیت</span><strong><?=e(ManagementMeetingsRepository::MEETING_STATUSES[$meeting['status']]??$meeting['status'])?></strong></div><div class="mg-detail"><span>تعداد مصوبات</span><strong><?=format_number($meeting['decision_count'])?></strong></div></div><h3>دستور جلسه</h3><p><?=nl2br(e($meeting['agenda']?:'ثبت نشده'))?></p><h3>خلاصه مذاکرات</h3><p><?=nl2br(e($meeting['meeting_summary']?:'ثبت نشده'))?></p><h3>حاضرین</h3><p><?=e(implode('، ',array_map(fn($x)=>$userMap[$x]??('کاربر '.$x),$meeting['attendees'])))?></p><?php if($meeting['attachments']):?><h3>پیوست‌ها</h3><div class="mg-actions"><?php foreach($meeting['attachments'] as $i=>$a):?><a class="btn btn-small" href="/admin/management-meeting-attachment.php?id=<?=$meeting['id']?>&index=<?=$i?>"><?=e($a['original_name']??'پیوست')?></a><?php endforeach?></div><?php endif?></section>
<section class="card"><h2>مصوبات جلسه</h2><div class="table-wrap"><table><thead><tr><th>مصوبه</th><th>مسئول / واحد</th><th>مهلت</th><th>وضعیت</th><th>پیشرفت</th><th></th></tr></thead><tbody><?php foreach($decisions as $d):?><tr class="<?=$d['display_status']==='overdue'?'mg-overdue-row':''?>"><td><strong><?=e($d['title'])?></strong><small><?=e(ManagementMeetingsRepository::PRIORITIES[$d['priority']]??$d['priority'])?></small></td><td><?=e($d['responsible_name']??'—')?><small><?=e($d['responsible_unit_title']??'—')?></small></td><td><?=e(JalaliDate::toJalali($d['due_date']))?></td><td><span class="mg-badge mg-status-<?=e($d['display_status'])?>"><?=e(ManagementMeetingsRepository::DECISION_STATUSES[$d['display_status']]??$d['display_status'])?></span></td><td><div class="mg-progress"><i style="width:<?=(int)$d['progress_percent']?>%"></i></div><small><?=(int)$d['progress_percent']?>٪</small></td><td><a class="btn btn-small" href="/admin/management-decision-view.php?id=<?=$d['id']?>">جزئیات</a></td></tr><?php endforeach?><?php if(!$decisions):?><tr><td colspan="6"><div class="mg-empty">هنوز مصوبه‌ای برای این جلسه ثبت نشده است.</div></td></tr><?php endif?></tbody></table></div></section>
<?php if(ManagementMeetingsRepository::canCreateMeeting($u)):?><section class="card" id="decisionForm"><h2>ثبت مصوبه جدید</h2><form method="post" class="mg-form-grid"><input type="hidden" name="_csrf" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="meeting_id" value="<?=$meeting['id']?>"><label>عنوان مصوبه<input name="title" maxlength="255" required></label><label>نوع مصوبه<select name="decision_type"><?php foreach(ManagementMeetingsRepository::DECISION_TYPES as $k=>$v):?><option value="<?=$k?>"><?=e($v)?></option><?php endforeach?></select></label><label>دسته‌بندی<input name="category" maxlength="100"></label><label>اولویت<select name="priority"><?php foreach(ManagementMeetingsRepository::PRIORITIES as $k=>$v):?><option value="<?=$k?>"><?=e($v)?></option><?php endforeach?></select></label><label>مسئول پیگیری<select name="responsible_user_id"><option value="">انتخاب</option><?php foreach($users as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach?></select></label><label>واحد مسئول<select name="responsible_unit_id"><option value="">انتخاب</option><?php foreach($units as $x):?><option value="<?=$x['id']?>"><?=e($x['title'])?></option><?php endforeach?></select></label><label>ناظر / تأییدکننده<select name="supervisor_user_id"><option value="">انتخاب</option><?php foreach($users as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach?></select></label><label>مهلت انجام<?=app_date_input('due_date')?></label><label>وضعیت اولیه<select name="followup_status"><?php foreach(ManagementMeetingsRepository::DECISION_STATUSES as $k=>$v):if(!in_array($k,['verified','overdue'],true)):?><option value="<?=$k?>"><?=e($v)?></option><?php endif;endforeach?></select></label><label>درصد پیشرفت<input type="number" name="progress_percent" min="0" max="100" value="0"></label><label><input type="checkbox" name="is_rule" value="1"> نامزد تبدیل به قانون</label><label>تاریخ اجرای قانون<?=app_date_input('rule_effective_date')?></label><label>تاریخ انقضای قانون<?=app_date_input('rule_expire_date')?></label><label class="wide">شرح مصوبه<textarea name="description" rows="5"></textarea></label><label class="wide">یادداشت اولیه<textarea name="latest_followup_note" rows="3"></textarea></label><div class="wide"><button class="btn btn-primary">ثبت مصوبه</button></div></form></section><?php endif?></div><?php require __DIR__.'/../views/partials/admin-footer.php';?>
